import {inputPipeline,checkpointTransfer,checkpointCommit,asyncQueue,checkpointTimeline,recoveryEnergy,eligibleGroups,localityRecovery,flexibleSchedule,recoveryChoices} from './storage-model.js';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const n=(v,d=0)=>v.toLocaleString('en-US',{maximumFractionDigits:d});
const arrow='<span class="flow-arrow" aria-hidden="true">→</span>';
const credit=(name,url)=>`<figcaption class="figure-credit"><a href="${url}" target="_blank" rel="noopener">${name}</a></figcaption>`;
const box=(title,detail='',className='')=>`<div class="flow-box ${className}"><b>${title}</b>${detail?`<span>${detail}</span>`:''}</div>`;
const fact=(value,label,className='')=>`<div class="fact ${className}"><strong>${value}</strong><span>${label}</span></div>`;
const condition=text=>`<p class="condition">${text}</p>`;
const photo=(src,alt,label,url)=>`<figure class="case-photo"><img src="../assets/references/${src}" alt="${alt}">${credit(label,url)}</figure>`;
const rack=()=>`<div class="rack-icon" aria-hidden="true">${'<i></i>'.repeat(6)}</div>`;
const disk=()=>`<div class="disk-icon" aria-hidden="true">${'<i></i>'.repeat(3)}</div>`;
const T=(x,y,text,size=23,color='ink',anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" fill="var(--${color})" text-anchor="${anchor}">${text}</text>`;
const R=(x,y,w,h,color='teal')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="var(--${color})"/>`;
const svg=(body,label,w=1100,h=420)=>`<svg class="storage-diagram" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
function purpose(){return `<div class="purpose-path"><section>${disk()}<h2>Data</h2><p>Prepare the next batch.</p></section><div class="purpose-center"><div class="direction">Dataset →</div>${rack()}<b>Training job</b><div class="direction">Checkpoint →</div></div><section><div class="saved-state" aria-hidden="true">✓<span>Step 42</span></div><h2>Saved progress</h2><p>Continue after a fault.</p></section></div><div class="purpose-question">What makes these powered GPUs produce recoverable work?</div>`;}
function pipeline(state){const b=inputPipeline({hostGBps:state.hostRate});return `<div class="pipeline"><div class="pipeline-path">${box('Storage','16 GB/s',b.bottlenecks.includes('source')?'bottleneck':'')}${arrow}${box('Network','24 GB/s')}${arrow}${box('Host preparation',`${state.hostRate} GB/s`,b.bottlenecks.includes('host')?'bottleneck':'')}${arrow}${box('GPU batches','Need 12 GB/s','gpu-box')}</div><div class="pipeline-result"><div class="supply-meter"><div><i style="width:${b.activeFraction*100}%"></i></div><span>${n(b.activeFraction*100)}% of input demand supplied</span></div>${fact(`${n(b.deliveredGBps)} GB/s`,'Delivered to the job')}<p>${b.activeFraction<1?'The host cannot prepare batches as fast as the GPU consumes them.':'The GPU has enough input; excess upstream capacity does not make it compute faster.'}</p></div></div>${condition('Same uncompressed payload at every boundary · overlapped stages · no prefilled batch buffer')}`;}
function roles(){return `<div class="three-roles"><section>${disk()}<h2>Dataset</h2><p>The input the run is meant to learn from.</p><b>Identify the version.</b></section><section><div class="cache-icon" aria-hidden="true">COPY</div><h2>Cache</h2><p>A reusable copy near the readers.</p><b>Know how to refill it.</b></section><section><div class="saved-state" aria-hidden="true">✓<span>Step 42</span></div><h2>Checkpoint</h2><p>The saved state of this training run.</p><b>Know which fault it survives.</b></section></div><div class="role-interfaces"><span><b>Local</b> · attached to a node</span><span><b>Shared</b> · accessible by several nodes</span><span><b>Object</b> · addressed through an object API</span></div>`;}
function metadata(state){const b=checkpointTransfer({shards:state.shards});return `<div class="metadata-story"><div class="three-metrics">${fact('512 GB','One checkpoint’s payload')}${fact('20 GB/s','Backend payload rate')}${fact('1,024 /s','Shard-creation operations')}</div><div class="shard-comparison"><div class="shard-cloud ${state.shards===65536?'many':''}" aria-hidden="true">${'<i></i>'.repeat(state.shards===65536?128:32)}</div><div>${fact(`${n(state.shards)} shards`,`${n(512/state.shards*1000,3)} MB per shard`)}<div class="equation">${n(state.shards)} ÷ 1,024 = <b>${n(b.metadataSeconds)} s</b></div><p>Create shard metadata before moving payload.</p></div></div><div class="capacity-line"><span>Retain three complete versions</span><b>3 × 512 GB = 1,536 GB</b><span>Before temporary space and redundancy</span></div></div>`;}
function rsc(){return `<div class="case-split rsc-case">${photo('storage-meta-rsc.jpg','Rows of racks in Meta’s Research SuperCluster.','Meta · Research SuperCluster · January 2022','https://ai.meta.com/blog/ai-rsc/')}<div class="case-content"><div class="tier-row"><strong>175 PB</strong><div><b>Bulk storage</b><span>Large dataset collection</span></div></div><div class="tier-row"><strong>46 PB</strong><div><b>Cache</b><span>Copies for repeated training access</span></div></div><div class="tier-row"><strong>10 PB</strong><div><b>NFS storage</b><span>Shared file access</span></div></div><p class="case-payoff">AIRStore preprocesses data once and reuses it across training runs until expiration.</p></div></div>`;}
function cache(state){const warm=state.cache==='warm';return `<div class="cache-path"><div class="cache-source ${warm?'dimmed':''}">${box('Dataset store','Versioned source')}${arrow}</div><div class="cache-tier">${box('Training cache',warm?'Requested data present':'Fetch and retain a copy',warm?'selected':'')}${arrow}</div><div class="cache-destination">${box('Training workers','Read prepared data')}</div></div><div class="cache-consequence"><strong>${warm?'Upstream read avoided':'Cold read reaches the dataset store'}</strong><p>${warm?'Reuse reduces repeated storage traffic and preprocessing.':'First access still needs the source path and permission to read it.'}</p></div>${condition('Cache eviction or loss returns this request to the cold path. ')}`;}
function checkpointState(){return `<div class="snapshot-layout"><div class="live-job"><h2>Training state at step 42</h2><div class="state-fields"><div><b>Model weights</b><span>Current learned parameters</span></div><div><b>Optimizer state</b><span>How the next update is computed</span></div><div><b>Run position</b><span>Step, sampler position and random state as required</span></div></div></div>${arrow}<div class="snapshot-version"><h2>Checkpoint 42</h2><div class="version-shards">${[1,2,3,4].map(x=>`<i><small>Shard ${x}</small><span>42</span></i>`).join('')}</div><div class="manifest"><b>Manifest</b><span>Version + required shards + dependencies</span></div></div></div><div class="dependency-strip"><span>Code revision</span><span>Environment</span><span>Dataset version</span><b>Must still be available at restart</b></div>`;}
function commit(state){const mode=state.commit,versions=mode==='partial'?[42,42,42,null]:mode==='mixed'?[42,42,42,43]:[42,42,42,42];const b=checkpointCommit({shards:versions,published:mode==='complete'});return `<div class="commit-story"><div class="checkpoint-version previous"><h2>Checkpoint 41</h2><div class="version-seal">✓</div><b>Already complete</b><span>Retained and recoverable</span></div><div class="checkpoint-version new"><h2>Checkpoint 42 attempt</h2><div class="commit-shards">${versions.map((v,i)=>`<div class="${v===null?'missing':v!==42?'wrong':''}"><span>Shard ${i+1}</span><strong>${v===null?'Missing':`Step ${v}`}</strong></div>`).join('')}</div><div class="manifest ${b.recoverable?'selected':''}"><b>${b.recoverable?'Manifest committed':'Manifest held back'}</b><span>${b.recoverable?'All required shards reached shared storage.':'The new version is not eligible for recovery.'}</span></div></div></div><div class="recovery-selection">Restart from <b>checkpoint ${b.recoveryVersion}</b><span>${mode==='mixed'?'Combining files from different steps does not recreate one training state.':mode==='partial'?'Three successful shard writes are not a complete distributed checkpoint.':'Publish the new recovery point only after its completion conditions pass.'}</span></div>`;}
function transfer(state){const b=checkpointTransfer({sourceGBps:state.sourceRate});return `<div class="transfer-path"><div class="pipeline-path">${box('Stage the state',`${state.sourceRate} GB/s`,state.sourceRate===16?'bottleneck':'')}${arrow}${box('Transfer','24 GB/s')}${arrow}${box('Persist','20 GB/s',state.sourceRate===32?'bottleneck':'')}</div><div class="transfer-equation">512 GB ÷ ${b.payloadGBps} GB/s = <b>${n(b.payloadSeconds,1)} seconds</b></div><div class="phase-account"><section><span>Create metadata</span><strong>4 s</strong><small>4,096 shards ÷ 1,024/s</small></section><span>+</span><section class="payload-phase"><span>Move payload</span><strong>${n(b.payloadSeconds,1)} s</strong><small>Stages above overlap</small></section><span>+</span><section><span>Commit version</span><strong>2 s</strong><small>Expose recovery point</small></section><span>=</span>${fact(`${n(b.totalSeconds,1)} s`,'Complete checkpoint')}</div></div>${condition('Metadata, payload and final commit run in sequence.')}`;}
function durability(state){const remote=state.durability==='remote';return `<div class="durability-layout"><div class="failed-node"><h2>Worker node fails</h2><div class="failure-cross" aria-hidden="true">×</div>${box('Local cache + local disk','Unavailable with this node')}</div><div class="durability-link ${remote?'':'dimmed'}"><span>${remote?'Checkpoint 42 committed →':'No independent copy of 42'}</span></div><div class="surviving-store">${disk()}<h2>Independent shared store</h2><div class="stored-versions"><span>Checkpoint 41 ✓</span>${remote?'<span class="new-version">Checkpoint 42 ✓</span>':''}</div><p>Survives this worker failure</p></div></div><div class="recovery-selection">Newest surviving recovery point <b>${remote?'42':'41'}</b><span>${remote?'Verify read access and restore the complete version on replacement workers.':'The local acknowledgement protected against different failures; it did not protect against losing this node.'}</span></div>`;}
function replication(state){const bad=state.replicaFault==='write';return `<div class="replica-layout"><section><h2>Live storage copies</h2><div class="replica-pair">${box('Copy A',bad?'Bad write applied':'Device failed','bottleneck')}${bad?arrow:'<span class="flow-arrow" aria-label="Failed device unavailable">×</span>'}${box('Copy B',bad?'Bad write replicated':'Healthy surviving copy',bad?'bottleneck':'selected')}</div><p>${bad?'Replicating a write can faithfully copy the application’s mistake.':'An independent replica keeps the data available after this one-device failure.'}</p></section><section><h2>Retained prior version</h2><div class="retained-version"><span class="version-seal">✓</span><b>Earlier valid version</b><span>Separate retention and recovery path</span></div><p>${bad?'Restore the earlier valid data, then reconcile changes made since it was saved.':'Restore remains an option if the live copies cannot supply valid data.'}</p></section></div><div class="gmail-case"><b>Gmail · 2011</b><span>A storage software bug affected replicated copies. Offline tape held a recovery copy; restoring the service still took hours.</span></div>${credit('Google · Gmail back soon for everyone · February 2011','https://gmail.googleblog.com/2011/02/gmail-back-soon-for-everyone.html')}`;}
function asyncSave(state){const done=state.asyncPhase===40;return `<div class="async-pair"><section><h2>Synchronous save</h2><div class="async-track"><i class="stage" style="width:20%">Stage</i><i class="persist" style="width:80%">Write + commit</i></div><div class="async-compute held"><span>Training waits for the save to finish.</span></div><b>40 s exposed pause</b></section><section><h2>Asynchronous save</h2><div class="async-track"><i class="stage" style="width:20%">Stage</i><i class="persist" style="width:80%">Write + commit</i></div><div class="async-compute"><i style="margin-left:20%;width:80%">Training resumes on live state →</i></div><b>8 s exposed pause</b></section></div><div class="snapshot-rule"><div><strong>Frozen snapshot</strong><span>Background saving reads the staged copy.</span></div><div><strong>Changing live state</strong><span>Training may mutate it after staging finishes.</span></div></div><div class="async-status ${done?'selected':''}">At ${state.asyncPhase} s: <b>${done?'checkpoint 42 is committed':'training resumes; checkpoint 41 is still the recovery point'}</b></div>${condition('8 s coherent staging + 32 s background write and commit · sufficient host buffers · no competing traffic')}`;}
function backlog(state){const b=asyncQueue({intervalSeconds:state.saveInterval});return `<div class="queue-layout"><div class="queue-rates">${fact(`${n(b.productionGBps,1)} GB/s`,'Requested checkpoint payload')}${fact('8 GB/s','Persistence rate')}${fact('2 snapshots','Host staging limit · 1,024 GB')}</div><table class="queue-table"><thead><tr><th>Save attempt</th><th>Requested</th><th>Staging admitted</th><th>Commit complete</th></tr></thead><tbody>${b.saves.map((s,i)=>`<tr class="${s.pauseSeconds?'waiting-row':''}"><th>${i+1}</th><td>${s.requested} s</td><td>${s.admitted} s${s.pauseSeconds?` <span>(${s.pauseSeconds} s wait)</span>`:''}</td><td>${s.end} s</td></tr>`).join('')}</tbody></table><div class="queue-result">${b.backpressured?'When both staging slots are occupied, the next save waits for a completed write.':'Each save finishes before the next attempt. Staging slots are released in time.'}</div></div>${condition('512 GB per snapshot · 64 s per write · wall-clock requests · one serial writer · staging time omitted')}`;}
function recoveryPath(){return `<div class="recovery-steps">${[
 ['1','Detect + stop','Notice the fault and stop stale workers.'],['2','Allocate','Find a feasible group of healthy workers.'],['3','Provision','Match the environment and data access.'],['4','Restore','Read one complete saved version.'],['5','Validate','Produce the first correct new output.'],
 ].map(([i,title,detail])=>`<section><span class="step-number">${i}</span><h2>${title}</h2><p>${detail}</p></section>`).join('')}</div><div class="objective-pair"><div><b>How much progress can be lost?</b><span>Recovery point objective</span></div><div><b>How soon must correct service resume?</b><span>Recovery time objective</span></div></div>`;}
function placement(state){const together=state.placement==='together',groups=together?[[true,true,true,true],[false,false,false,false]]:[[true,true,false,false],[true,true,false,false]];const b=eligibleGroups({groups});return `<div class="placement-request">Job needs <b>4 nodes × 8 GPUs</b> in one validated group, at the same time.</div><div class="placement-groups">${groups.map((g,i)=>`<section class="${b.eligible.includes(i)?'eligible':''}"><h2>Group ${i===0?'A':'B'}</h2><div class="placement-nodes">${g.map(free=>`<div class="${free?'free':'occupied'}">${rack()}<b>${free?'Free':'Busy'}</b><span>8 GPUs</span></div>`).join('')}</div></section>`).join('')}</div><div class="placement-result">${fact(`${b.freeGPUs} GPUs`,'Free hardware')}${fact(`${b.eligible.length}`,'Eligible four-node allocations',b.eligible.length?'':'warning')}<p>${b.eligible.length?'Reserve the group so all workers can launch together.':'Two partial groups cannot launch this job. A successful distributed restart needs the whole allocation.'}</p></div>`;}
function locality(state){const b=localityRecovery({waitSeconds:state.localWait});return `<div class="locality-pair"><section><h2>Wait for the group with a local copy</h2><div class="locality-parts"><span><b>${state.localWait} s</b> queue</span><span><b>12 s</b> setup</span><span><b>${b.localReadSeconds} s</b> restore</span></div>${fact(`${b.localReadySeconds} s`,'Ready to validate new output')}<p>512 GB ÷ 32 GB/s</p></section><section><h2>Use another eligible group now</h2><div class="locality-parts"><span><b>0 s</b> queue</span><span><b>12 s</b> setup</span><span><b>${b.remoteReadSeconds} s</b> restore</span></div>${fact(`${b.remoteReadySeconds} s`,'Ready to validate new output')}<p>512 GB ÷ 8 GB/s</p></section></div><div class="locality-decision">${b.localReadySeconds<b.remoteReadySeconds?'Waiting 30 seconds is worthwhile here: the faster restore saves 48 seconds.':'The longer queue now outweighs the faster local read.'}</div>${condition('Same committed checkpoint, compatible four-node groups and validation time · queue, setup and reads occur in sequence')}`;}
function llama(){return `<div class="llama-story"><div class="llama-metrics">${fact('54 days','Llama 3 training snapshot')}${fact('466','Training interruptions')}${fact('>90%','Effective training time')}</div><div class="interruption-breakdown"><div><strong>47</strong><span>Planned interruptions</span></div><div><strong>419</strong><span>Unexpected interruptions</span></div></div><div class="recovery-loop"><span>Automated diagnosis</span>${arrow}<span>Restart + restore</span>${arrow}<span>Training advances</span></div><p class="llama-payoff">Meta reduced startup and checkpoint overhead; only three incidents required major manual intervention.</p>${credit('Meta · The Llama 3 Herd of Models · §3.3.4','https://arxiv.org/html/2407.21783v3#S3.SS3.SSS4')}</div>`;}
const timelineLabels={work:'New progress',lost:'Lost work',save:'Save',recovery:'Recover'};
function policy(state,compact){const policies=[20,40].map(interval=>({interval,...checkpointTimeline({intervalMinutes:interval,failureMinute:state.failure})}));const w=compact?420:1100,h=compact?530:410,left=compact?35:55,right=compact?25:55,scale=(w-left-right)/110;let body='';for(const[p,b]of policies.entries()){const y=compact?90+p*200:75+p*170;body+=T(left,y-25,`Save every ${b.interval} useful minutes`,compact?21:25,'ink','start');for(const s of b.segments){body+=R(left+s.start*scale,y,s.duration*scale,48,{work:'teal',lost:'amber',save:'phase-three',recovery:'muted'}[s.kind]);if(s.duration>=10)body+=T(left+(s.start+s.end)/2*scale,y+30,String(n(s.duration)),compact?16:19,'paper');}body+=T(left+b.finishMinute*scale,y+77,`${b.finishMinute} min`,compact?18:22,'ink');body+=T(left,y+109,`${b.lostMinutes} min lost · ${b.saveMinutes} min saving`,compact?17:20,'muted','start');}
const axisY=h-25;body+=`<path d="M${left} ${axisY}H${w-right}" stroke="var(--line)" stroke-width="2"/>`;for(let t=0;t<=100;t+=20)body+=T(left+t*scale,axisY+22,String(t),compact?16:17,'muted');if(state.failure!==null)body+=`<path d="M${left+state.failure*scale} ${compact?90:75}v48M${left+state.failure*scale} ${compact?290:245}v48" stroke="var(--ink)" stroke-dasharray="5 5" stroke-width="2"/>`+T(left+state.failure*scale,20,'Fault',compact?16:20);
return `<div class="policy-layout">${svg(body,'Two timelines separate new useful progress, lost work, checkpoint saving and recovery.',w,h)}<div class="timeline-legend">${Object.entries(timelineLabels).map(([kind,label])=>`<span class="legend-${kind}"><i></i>${label}</span>`).join('')}</div><div class="policy-verdict">${state.failure===35?'At minute 35, the 20-minute policy has preserved 20 useful minutes; the other has preserved none.':state.failure===55?'At minute 55, both policies have preserved 40 useful minutes. Both finish at minute 80.':'Without a fault, the 40-minute policy saves once and finishes two minutes sooner.'}</div></div>${condition('60 useful minutes required · 2 min per synchronous save · 5 min restoration · initial checkpoint at zero · no final save')}`;}
function energy(){const entries=[20,40].map(interval=>{const t=checkpointTimeline({intervalMinutes:interval});return{interval,t,e:recoveryEnergy(t)}});return `<div class="energy-layout"><div class="power-inputs"><span><b>1 MW</b> computing</span><span><b>0.8 MW</b> saving</span><span><b>0.4 MW</b> restoring</span></div><div class="energy-pair">${entries.map(({interval,t,e})=>`<section><h2>Save every ${interval} useful minutes</h2><div class="energy-bar">${[['usefulMWh','work'],['lostMWh','lost'],['saveMWh','save'],['recoveryMWh','recovery']].map(([key,kind])=>`<i class="energy-${kind}" style="width:${e[key]/1.7*100}%" title="${timelineLabels[kind]}: ${n(e[key],3)} MWh"></i>`).join('')}</div>${fact(`${n(e.totalMWh,3)} MWh`,'Total cluster IT energy')}<div class="energy-detail"><span>New progress <b>1 MWh</b></span><span>Repeated work <b>${n(e.lostMWh,3)} MWh</b></span><span>Save + restore <b>${n(e.saveMWh+e.recoveryMWh,3)} MWh</b></span></div></section>`).join('')}</div><div class="energy-equation">Energy = power × time <span>13 min lost × 1 MW ÷ 60 = 0.217 MWh</span></div></div>${condition('Same 60-minute useful job · fault at wall-clock minute 35 · fixed cluster IT power by phase · cooling outside this energy account')}`;}
function provision(state){const valid=state.environment==='validated';return `<div class="provision-grid"><section><h2>Environment</h2><div class="manifest-file"><span>Code <b>revision a7</b></span><span>Container <b>image 12</b></span><span>Host drivers <b>validated set</b></span><span class="${valid?'':'mismatch'}">Runtime <b>${valid?'version 6 on all workers':'6 on peers · 7 on restart'}</b></span></div><p>${valid?'Distributed initialization uses the tested version set.':'A GPU may be discoverable while the distributed job still fails to initialize.'}</p></section><section><h2>Access and isolation</h2><div class="permission-lines"><span>✓ Read the intended dataset version</span><span>✓ Write to this job’s checkpoint path</span><span>✓ Restrict resources to this allocation</span><span>✓ Deny access outside the tenant boundary</span></div><div class="isolation-rule"><b>Monitoring records use.</b><span>Enforcement constrains use and access.</span></div></section></div>`;}
function flex(){return `<div class="flex-pair"><section><div class="workload-icon">200 ms</div><h2>Interactive response</h2><p>The user is waiting for this request.</p><div class="service-limit">Two hours of delay misses the response requirement.</div></section><section><div class="workload-icon">20:00</div><h2>Batch video processing</h2><p>Output is needed by this evening.</p><div class="service-limit flexible">A pause may fit if saved progress, later capacity and the deadline permit it.</div></section></div><div class="flex-requirements"><span>Deadline</span><span>Restart cost</span><span>Data access</span><span>Later capacity</span></div>`;}
function google(){return `<div class="case-split google-case">${photo('storage-google-dalles-repair.jpg','A Google technician replaces a motherboard at The Dalles data center.','Google · The Dalles, Oregon · facility operations','https://www.datacenters.google/discover-more/photo-gallery/')}<div class="case-content"><h2>The Dalles, Oregon</h2><p>Google’s 2023 account describes a day-ahead pilot with Northern Wasco County PUD.</p><div class="google-event-path">${box('Grid event notice','Identify the constrained hours')}<span aria-hidden="true">↓</span>${box('Limit non-urgent work','Global planner assigns hourly budgets')}<span aria-hidden="true">↓</span>${box('Reschedule eligible jobs','Later, or elsewhere when feasible')}</div></div></div>${credit('Google Cloud · Supporting power grids with demand response · October 2023','https://cloud.google.com/blog/products/infrastructure/using-demand-response-to-reduce-data-center-power-consumption')}`;}
function schedule(state,compact){const b=flexibleSchedule({deadlineHour:state.deadline,shift:state.shift}),w=compact?420:1100,h=compact?350:330,left=compact?70:80,right=30,top=50,bottom=h-75,scale=(w-left-right)/8,py=p=>bottom-(p-18)/(26-18)*(bottom-top),x=t=>left+(t-13)*scale;let body=`<rect x="${x(14)}" y="${top-15}" width="${2*scale}" height="${bottom-top+15}" fill="var(--warning-surface)"/>`+T(x(15),top-25,'Grid event',compact?18:23,'amber');for(const p of[20,24])body+=`<path d="M${left} ${py(p)}H${w-right}" stroke="var(--line)" stroke-width="1"/>`+T(left-12,py(p)+6,`${p}`,compact?17:20,'muted','end');body+=T(15,top+15,'MW',compact?18:21,'muted','start');const breaks=[...new Set([13,21,...b.segments.flatMap(s=>[s.start,s.end])])].sort((a,b)=>a-b);let points=[];for(let i=0;i<breaks.length-1;i++){const start=breaks[i],end=breaks[i+1],on=b.segments.some(s=>start>=s.start&&start<s.end);points.push(`${x(start)},${py(on?24:20)}`,`${x(end)},${py(on?24:20)}`);}body+=`<polyline points="${points.join(' ')}" fill="none" stroke="var(--teal)" stroke-width="4"/>`+`<path d="M${x(state.deadline)} ${top-10}V${bottom+7}" stroke="var(--ink)" stroke-width="2" stroke-dasharray="6 5"/>`+T(x(state.deadline),bottom+52,'Deadline',compact?15:18);for(let t=13;t<=21;t+=compact?2:1)body+=T(x(t),bottom+30,`${t}:00`,compact?16:17,'muted');return `<div class="schedule-layout">${svg(body,`Power from 13:00 to 21:00. The job ${state.shift?'pauses from 14:00 to 16:00':'continues during the grid event'}, finishes at ${b.finishHour}:00, and ${b.meetsDeadline?'meets':'misses'} its deadline.`,w,h)}<div class="schedule-results">${fact(`${b.finishHour}:00`,'Job completes',b.meetsDeadline?'':'warning')}${fact(`${b.eventPeakMW} MW`,'Peak during grid event')}${fact(`${b.jobMWh} MWh`,'Job energy in either plan')}</div><div class="schedule-verdict ${b.meetsDeadline?'':'warning'}">${!b.meetsDeadline?'This shifted schedule misses the deadline. Keep capacity during the event or change the accepted plan.':state.shift?'The job finishes on time. Demand returns to 24 MW afterward; that capacity must remain available.':'The job finishes early, while its 4 MW demand overlaps the grid event.'}</div></div>${condition('20 MW base + 4 MW job · 3 useful hours · pause/resume overhead omitted · no work lost · later 24 MW capacity available')}`;}
function acceptance(){return `<div class="acceptance-brief"><span>Tenant acceptance brief</span><p>Run a pinned workload from a cold cache, save it, terminate one test worker, and recover correct progress within the agreed deadline.</p></div><div class="acceptance-grid"><section><span>01</span><h2>Reproduce the input</h2><p>Code, environment and dataset identifiers match the declared run.</p></section><section><span>02</span><h2>Meet the service target</h2><p>Correct output and sustained throughput pass under the specified background load.</p></section><section><span>03</span><h2>Recover saved progress</h2><p>The chosen checkpoint restores on an eligible group and produces correct new output.</p></section><section><span>04</span><h2>Leave usable evidence</h2><p>Stage timings, output checks and cleanup identify what passed and what failed.</p></section></div>`;}
function diagnosis(state){const choice=recoveryChoices[state.diagnosis];return `<div class="diagnosis-grid"><section class="diagnosis-evidence"><h2>One worker has failed</h2><dl><dt>Saved state</dt><dd>42 committed to shared storage.<br>43 missing one shard.</dd><dt>Failed node</dt><dd>Node and local cache unavailable.</dd><dt>Required allocation</dt><dd>4 nodes in one validated group.</dd><dt>Free now</dt><dd>2 nodes in A + 2 nodes in B.</dd><dt>In 30 seconds</dt><dd>All 4 nodes in A become free.</dd><dt>Recovery target</dt><dd>First correct new output within 5 minutes.</dd></dl></section><div class="diagnosis-options">${[['newest','Restart from checkpoint 43: it is newer.'],['split','Use checkpoint 42 on the four nodes free now.'],['restore','Reserve Group A, then restore committed checkpoint 42.'],['cache','Recover 43 from the failed node’s cache.']].map(([key,label])=>`<button data-diagnosis="${key}" aria-pressed="${state.diagnosis===key}">${label}</button>`).join('')}</div></div><button id="diagnosis-reveal" ${!choice?'disabled':''}>${state.showDiagnosis?'Hide reasoning':'Check the recovery plan'}</button><div class="diagnosis-response" role="status">${state.showDiagnosis&&choice?`<p><b>${choice.correct?'A feasible recovery plan.':'One required condition is missing.'}</b> ${choice.text}${choice.correct?' Time the full recovery path against the five-minute target; allocation alone does not prove it.':''}</p>`:''}</div>`;}
export function storageVisual(id,state,compact=false){switch(id){
 case'hardware-prices-meme':return `<figure class="meme-figure"><img src="../assets/references/storage-hardware-prices-meme.png" alt="A post titled CPU, you're next. The Grim Reaper, labeled AI, passes doors marked RAM prices, GPU prices and SSD prices, and knocks on CPU prices."></figure>`;
 case'storage-purpose':return purpose();case'input-pipeline':return pipeline(state);case'storage-roles':return roles();case'metadata-pressure':return metadata(state);case'meta-rsc':return rsc();case'cache-hit':return cache(state);case'checkpoint-state':return checkpointState();case'checkpoint-commit':return commit(state);case'checkpoint-time':return transfer(state);case'durability-boundary':return durability(state);case'replication-and-backup':return replication(state);case'async-checkpoint':return asyncSave(state);case'save-backlog':return backlog(state);case'recovery-path':return recoveryPath();case'recovery-placement':return placement(state);case'recovery-locality':return locality(state);case'llama-recovery':return llama();case'checkpoint-policy':return policy(state,compact);case'recovery-energy':return energy();case'provision-and-isolate':return provision(state);case'flexible-jobs':return flex();case'google-demand-response':return google();case'deadline-scheduling':return schedule(state,compact);case'service-acceptance':return acceptance();case'recovery-diagnosis':return diagnosis(state);default:throw new Error(`No storage visual for ${id}`);
}}
